INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000006f',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe family relationships in depth in Kannada","Use extended family vocabulary","Talk about family dynamics and roles"],"explanation":{"intro":"Extended family vocabulary covers grandparents, aunts, uncles, cousins, in-laws, and family roles — essential for Karnataka family culture where joint and extended family relationships are central.","culturalNote":"Family culture in Karnataka: (1) Joint family: still common in Karnataka — especially in smaller towns. ''Kutumba'' (extended family) is a valued unit. (2) Extended family terms: Kannada has very specific words for each family member that distinguish maternal/paternal sides and age relative to parents. (3) Marriage: arranged marriage (arranged marriage or niroopita vivaha) is still common alongside love marriages (love marriage). (4) In-laws: maava (father-in-law — for women), attey (mother-in-law — for women), aliya (son-in-law), sudina (daughter-in-law). (5) Maternal uncle: maava or doddappa depending on region. (6) Family gathering (kutumba samaavesh): during Dasara, Ugaadi, Sankranti — the whole family assembles. (7) Elder respect: addressing elders correctly is very important — using ''neevu'' (you — formal) for older relatives. (8) Children addressing parents: amma (mother — universal), appa/anna (father — appa common, anna in some regions). (9) Siblings: anna (older brother), akka (older sister), tamma (younger brother), tangi (younger sister)."},"examples":[{"sentence":"Namma kutumba thumba dodda — naanna ajja-ajji, doddappa-dodDamma, chikkappa-chikkamma ellaaruu hattira iru.","english":"Our family is very large — my grandparents, paternal uncle-aunt, younger uncle-aunt, everyone is together."},{"sentence":"Nanna akka ee tiNgaLu Bengaluru ge mane kaTTidaaLe — hosa mane, hosa jiivana shuru.","english":"My elder sister built a house in Bengaluru this month — new house, new life beginning."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe extended family relationships and family dynamics in Kannada."}}',
'{"items":[{"word":"kutumba","translation":"extended family / family unit","transliteration":"kutumba","pronunciation":"ku-TUM-ba","example":"namma kutumba"},{"word":"doddappa","translation":"paternal uncle (father''s elder brother)","transliteration":"doddappa","pronunciation":"dod-DAP-pa","example":"nanna doddappa"},{"word":"chikkappa","translation":"paternal uncle (father''s younger brother)","transliteration":"chikkappa","pronunciation":"chik-KAP-pa","example":"nanna chikkappa"},{"word":"dodDamma","translation":"paternal aunt (father''s elder brother''s wife)","transliteration":"dodDamma","pronunciation":"dod-DAM-ma","example":"nanna dodDamma"},{"word":"aliya","translation":"son-in-law","transliteration":"aliya","pronunciation":"a-LI-ya","example":"nanna aliya"},{"word":"sudina","translation":"daughter-in-law","transliteration":"sudina","pronunciation":"su-DI-na","example":"nanna sudina"}]}',
'{"title":"Kannada extended family vocabulary — kutumba","pattern":"Nanna X (relationship) Y (name/place) alli iru = My X (relation) is at Y. Kutumba dodda = family is large. X ella hattira iru = X all are together. Family events: kutumba samaavesh (family gathering). Age-based terms: dodd- prefix = elder, chikk- prefix = younger (doddappa = elder uncle, chikkappa = younger uncle).","explanation":"Kannada family vocabulary is very specific: maternal vs paternal distinction: (maternal side) aavana = maternal uncle (mother''s brother), aave = maternal aunt; (paternal side) doddappa/chikkappa = elder/younger paternal uncle. Age distinction: dodda (elder), chikka (younger). In-laws: maava (father-in-law), attey (mother-in-law), aliya (son-in-law), sudina (daughter-in-law). Cousins: no specific word — referred to as ''anna/akka/tamma/tangi'' (elder brother/sister/younger brother/sister) depending on age and relationship. Joint family talk: hattira iru (living together), ella seri iru (all living together), ooru inda baruttaare (coming from the village — visiting). Describing family: namma kutumba thumba dodda/chikka (our family is very large/small), hattira iru/dooradalli iru (living together/far away).","examples":[{"sentence":"Nanna aavana family Mysuru alli iru — habbagaLalli namma family ellaa Bengaluru ge bandu seri oota maaDuttive.","english":"My maternal uncle''s family is in Mysuru — at festivals our whole family comes to Bengaluru and eats together."},{"sentence":"Nanna tamma ee year engineering poorthi maaDuttaane — avanu future alli IT alli kaela maaDabeku anta wish ide.","english":"My younger brother will complete engineering this year — there is a wish that he should work in IT in the future."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"chikkappa means?","options":["paternal uncle (father''s younger brother)","maternal uncle","elder uncle","grandfather"],"correctAnswer":"paternal uncle (father''s younger brother)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Our family is very large — my grandparents, paternal uncle-aunt, younger uncle-aunt, everyone is together.","options":["Namma kutumba thumba dodda — naanna ajja-ajji, doddappa-dodDamma, chikkappa-chikkamma ellaaruu hattira iru.","Nimma kutumba thumba dodda — naanna ajja-ajji, doddappa-dodDamma, chikkappa-chikkamma ellaaruu hattira iru.","Namma kutumba thumba chikka — naanna ajja-ajji, doddappa-dodDamma, chikkappa-chikkamma ellaaruu hattira iru.","Namma kutumba thumba dodda — naanna appa-amma, doddappa-dodDamma, chikkappa-chikkamma ellaaruu hattira iru."],"correctAnswer":"Namma kutumba thumba dodda — naanna ajja-ajji, doddappa-dodDamma, chikkappa-chikkamma ellaaruu hattira iru."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna tamma ee year engineering poorthi maaDuttaane — avanu future alli IT alli kaela maaDabeku anta ___ ide.","options":["wish","plan","samasye","problem"],"correctAnswer":"wish"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My maternal uncle''s family is in Mysuru — at festivals our whole family comes to Bengaluru and eats together.","wordBankItems":["Nanna","aavana","family","Mysuru","alli","iru","—","habbagaLalli","namma","family","ellaa","Bengaluru","ge","bandu","seri","oota","maaDuttive","."],"correctAnswer":"Nanna aavana family Mysuru alli iru — habbagaLalli namma family ellaa Bengaluru ge bandu seri oota maaDuttive ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aliya means?","options":["son-in-law","daughter-in-law","nephew","cousin"],"correctAnswer":"son-in-law"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000070',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe emotions and mental states in Kannada","Use emotional vocabulary beyond santosha and dukha","Express nuanced feelings — loneliness, excitement, nostalgia"],"explanation":{"intro":"Emotional vocabulary covers nuanced feelings — going beyond basic happy/sad to express loneliness, nostalgia, excitement, anxiety, pride, and contentment in Kannada.","culturalNote":"Emotional expression in Karnataka: Kannadigas are generally considered to be emotionally reserved in public but very warm and expressive in private settings. (1) Nostalgia: ''namma ooru'' (our village/hometown) evokes strong nostalgia for Bengaluru migrants. ''Hale Bengaluru'' (old Bengaluru) nostalgia. (2) Pride: Kannada pride (Kannada pride/Kannadabhimana) is a strong emotion — felt strongly on Rajyotsava. (3) Loneliness: increasingly discussed in urban Bengaluru — IT professionals far from native places. (4) Film: Kannada films are known for emotional depth — family drama and sentiment are central to Sandalwood's appeal. (5) Religious emotion: bhakti (devotion) is a strong emotion — pilgrimage experiences, temple darshana. (6) Music and emotion: Kannada bhavageethe are specifically designed to evoke deep emotions — ''mana'' (heart/mind) is a central concept in Kannada lyric poetry. (7) ''Haayenisuttade'' (I feel relieved/peaceful) — a very typically Kannada expression of quiet contentment."},"examples":[{"sentence":"Bengaluru ge banda badalaava alli naakke swalpav loneliness aagutte — namma ooru miss aagutte, family miss aagutte.","english":"After coming to Bengaluru I feel a little loneliness — I miss our hometown, I miss family."},{"sentence":"Naale exam results barutte — naakke thumba anxiety ide aadare confident aagiruvaante yochisuttiddeeni.","english":"Tomorrow exam results are coming — I have a lot of anxiety but I am trying to think like I am confident."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe nuanced emotions and mental states in Kannada."}}',
'{"items":[{"word":"loneliness","translation":"loneliness (English — commonly used)","transliteration":"loneliness","pronunciation":"LON-li-nes","example":"swalpav loneliness"},{"word":"anxiety","translation":"anxiety/worry","transliteration":"anxiety","pronunciation":"ang-ZAI-i-ti","example":"thumba anxiety ide"},{"word":"nostalgic","translation":"nostalgic / feeling nostalgic","transliteration":"nostalgic","pronunciation":"nos-TAL-jik","example":"naakke nostalgic aagutte"},{"word":"proud","translation":"proud (naakke proud aagutte)","transliteration":"proud","pronunciation":"prawd","example":"naakke proud aagutte"},{"word":"haayenisuttade","translation":"I feel relieved/at peace (uniquely Kannada contentment expression)","transliteration":"haayenisuttade","pronunciation":"haa-ye-NI-sut-ta-de","example":"illi bandu haayenisuttade"},{"word":"bhakti","translation":"devotion/religious devotion","transliteration":"bhakti","pronunciation":"BHAK-ti","example":"devara mele bhakti"}]}',
'{"title":"Emotional vocabulary — nuanced feelings in Kannada","pattern":"Naakke X aagutte = I feel X. X miss aagutte = I miss X. Naakke proud aagutte = I feel proud. Haayenisuttade = I feel at peace/relieved. Anxiety: naakke anxiety ide / chintane aagutte (I feel anxious/worried). Nostalgia: namma ooru nodidaaga nostalgic aagutte (I feel nostalgic seeing my hometown). Pride: naakke Kannada mele thumba pride ide (I have a lot of pride in Kannada).","explanation":"Emotional vocabulary in Kannada: basic (A1): santosha (happiness), dukha (sadness), raaga (anger), bhaya (fear). Advanced (A2): (1) Loneliness: loneliness (English), ekante (solitude — more positive connotation). (2) Anxiety: anxiety (English), chintane (worry — Kannada), udwega (stress/agitation — formal). (3) Nostalgia: nostalgic (English), hinde naDavali (past memory/nostalgia). (4) Pride: proud (English), abhimaana (pride/self-respect — Kannada). (5) Relief: haayenisuttade (I feel relieved — uniquely Kannada). (6) Contentment: samaadhaana ide (I feel content). (7) Excitement: excitement ide (I have excitement), thumba khushi ide (very happy). (8) Overwhelm: overwhelm aagutte (I feel overwhelmed). (9) Devotion: bhakti ide (I feel devotion). Expressing about others: avakke sad aagutte anta kaaNuttide (it seems they are feeling sad).","examples":[{"sentence":"Kannadabhimana anta heLidaaga naakke thumba proud haagu emotional aagutte — idu namma bhaashe, namma astitva.","english":"When you say Kannadabhimana I feel very proud and emotional — this is our language, our identity."},{"sentence":"Exam poorthi aadanantara naakke thumba haayenisuttade — 6 thinagaLa stress ekha dina alli hogide.","english":"After the exam was over I felt very relieved — 6 months of stress went away in one day."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"haayenisuttade means?","options":["I feel relieved/at peace (Kannada contentment)","I feel sad","I feel happy","I feel excited"],"correctAnswer":"I feel relieved/at peace (Kannada contentment)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"After coming to Bengaluru I feel a little loneliness — I miss our hometown, I miss family.","options":["Bengaluru ge banda badalaava alli naakke swalpav loneliness aagutte — namma ooru miss aagutte, family miss aagutte.","Mysuru ge banda badalaava alli naakke swalpav loneliness aagutte — namma ooru miss aagutte, family miss aagutte.","Bengaluru ge banda badalaava alli naakke thumba loneliness aagutte — namma ooru miss aagutte, family miss aagutte.","Bengaluru ge banda badalaava alli naakke swalpav loneliness aagutte — namma ooru miss aagutte, geleja miss aagutte."],"correctAnswer":"Bengaluru ge banda badalaava alli naakke swalpav loneliness aagutte — namma ooru miss aagutte, family miss aagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Exam poorthi aadanantara naakke thumba ___ — 6 thinagaLa stress ekha dina alli hogide.","options":["haayenisuttade","anxiety ide","loneliness aagutte","nostalgic aagutte"],"correctAnswer":"haayenisuttade"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: When you say Kannadabhimana I feel very proud and emotional — this is our language, our identity.","wordBankItems":["Kannadabhimana","anta","heLidaaga","naakke","thumba","proud","haagu","emotional","aagutte","—","idu","namma","bhaashe",",","namma","astitva","."],"correctAnswer":"Kannadabhimana anta heLidaaga naakke thumba proud haagu emotional aagutte — idu namma bhaashe , namma astitva ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"bhakti means?","options":["devotion/religious devotion","love","respect","prayer"],"correctAnswer":"devotion/religious devotion"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000071',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe Karnataka''s natural beauty in Kannada","Use landscape and biodiversity vocabulary","Discuss the Western Ghats and Karnataka''s geography"],"explanation":{"intro":"Karnataka''s natural beauty vocabulary covers the diverse landscapes — from the Western Ghats biodiversity hotspot to the Deccan plateau, coastline, and rivers.","culturalNote":"Karnataka''s natural geography: Karnataka is one of India''s most geographically diverse states. (1) Western Ghats (Sahyadri): a UNESCO World Heritage Site and one of the 8 biodiversity hotspots in the world. Covers Dakshina Kannada, Kodagu, Hassan, Shivamogga districts. Rich in endemic species — lion-tailed macaque, purple frog, Malabar giant squirrel. (2) Rivers: Kaveri (Cauvery — Karnataka''s most important river — originates at Talakaveri in Kodagu), Tungabhadra (famous for Hampi), Krishna, Sharavathi (Jog Falls), Malaprabha, Ghataprabha. (3) Jog Falls: Karnataka''s most famous waterfall (256m) — Sharavathi River — one of India''s highest waterfalls. (4) Coast: Karnataka''s coast (Dakshina Kannada, Udupi, Uttara Kannada districts — ''Karavali'' = the coastal zone). Mangaluru, Udupi, Gokarna, Karwar. (5) Deccan Plateau (Maidan): central and northern Karnataka — black cotton soil, millet farming. (6) Forests: 20% of Karnataka is forest — tiger reserves (Nagarhole, Bandipur, BRT), elephant corridors. (7) Coffee: Kodagu and Chikmagalur — India''s top coffee-growing regions."},"examples":[{"sentence":"Karnataka praakRitika soundarya thumba vividha — mele Western Ghats kaadu, keLage Karavali samudra, madhyada Deccan maidan.","english":"Karnataka''s natural beauty is very diverse — above Western Ghats forest, below Karavali sea, middle Deccan plateau."},{"sentence":"Jog Falls nodidaaga manassu tumbitu — Sharavathi nadi inda 256 metre uchi inda neeru biDuttade, thumba adbhuta.","english":"When I saw Jog Falls my heart filled up — from the Sharavathi river water falls from 256 metres height, truly wonderful."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe Karnataka''s natural beauty and geographical diversity in Kannada."}}',
'{"items":[{"word":"praakRitika soundarya","translation":"natural beauty","transliteration":"praakRitika soundarya","pronunciation":"praak-RI-ti-ka SAWN-dar-ya","example":"Karnataka praakRitika soundarya"},{"word":"vividha","translation":"diverse/varied","transliteration":"vividha","pronunciation":"VI-vi-dha","example":"thumba vividha"},{"word":"Karavali","translation":"the coastal zone of Karnataka (coastal belt)","transliteration":"Karavali","pronunciation":"ka-ra-VA-li","example":"Karavali samudra"},{"word":"samudra","translation":"sea/ocean","transliteration":"samudra","pronunciation":"sa-MUD-ra","example":"Arabian samudra"},{"word":"uchi","translation":"height/altitude","transliteration":"uchi","pronunciation":"U-chi","example":"256 metre uchi"},{"word":"biodiversity","translation":"biodiversity (English — scientific context)","transliteration":"biodiversity","pronunciation":"bai-o-dai-VUR-si-ti","example":"Western Ghats biodiversity"}]}',
'{"title":"Karnataka''s natural beauty vocabulary","pattern":"X praakRitika soundarya thumba vividha = X''s natural beauty is very diverse. X mele/keLage/madhyada Y = Y above/below/in the middle of X (geographical description). Jog Falls alli neeru X uchi inda biDuttade = at Jog Falls water falls from X height. Western Ghats UNESCO heritage site — biodiversity hotspot.","explanation":"Nature vocabulary in Kannada: praakRitika (natural — adjective), soundarya (beauty), vividha (diverse), samrudda (rich/abundant — biodiversity), samsiddha (endowed with — richly blessed). Geographical features: betta/giri (hill/mountain), naadi (river), samudra (sea/ocean), kaadu (forest), jalapaata (waterfall), maidan (plateau/plains). Rivers: Kaveri, Tungabhadra, Sharavathi, Krishna, Malaprabha. Wildlife: huli (tiger), aane/gaja (elephant), kaDave/chiretha (leopard), pakshi (bird). Flora: kaafi (coffee plant), teakwood (teakwood), bamboo (bamboo), mara (tree). Conservation: samrakshaNe (conservation), rakshaNe (protection), UNESCO heritage. Seasons affecting nature: monsoon (varsha)= forest turns lush green, summer (beshige)= rivers reduce, winter (sheetakala)= fog in Ghats.","examples":[{"sentence":"Western Ghats alli huli, aane, chiretha — thumba wildlife ide, samrakshaNe thumba muhtvadadu.","english":"In the Western Ghats there are tigers, elephants, leopards — there is a lot of wildlife, conservation is very important."},{"sentence":"Namma Kaveri naadi Karnataka ge jiivanadi — Kodagu inda huttond iii naadi Bengaluru kaakke neeru koDuttade.","english":"Our Kaveri river is Karnataka''s lifeline — originating from Kodagu, this river gives water to Bengaluru too."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"praakRitika soundarya means?","options":["natural beauty","cultural heritage","wildlife sanctuary","biodiversity"],"correctAnswer":"natural beauty"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Karnataka''s natural beauty is very diverse — above Western Ghats forest, below Karavali sea, middle Deccan plateau.","options":["Karnataka praakRitika soundarya thumba vividha — mele Western Ghats kaadu, keLage Karavali samudra, madhyada Deccan maidan.","Karnataka praakRitika soundarya swalpa vividha — mele Western Ghats kaadu, keLage Karavali samudra, madhyada Deccan maidan.","Karnataka praakRitika soundarya thumba vividha — keLage Western Ghats kaadu, mele Karavali samudra, madhyada Deccan maidan.","Karnataka praakRitika soundarya thumba vividha — mele Western Ghats kaadu, keLage Arabian samudra, madhyada Deccan maidan."],"correctAnswer":"Karnataka praakRitika soundarya thumba vividha — mele Western Ghats kaadu, keLage Karavali samudra, madhyada Deccan maidan."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Namma Kaveri naadi Karnataka ge jiivanadi — Kodagu inda huttond iii naadi Bengaluru ___ neeru koDuttade.","options":["kaakke","maatrada","alli","inda"],"correctAnswer":"kaakke"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: When I saw Jog Falls my heart filled up — from the Sharavathi river water falls from 256 metres height, truly wonderful.","wordBankItems":["Jog","Falls","nodidaaga","manassu","tumbitu","—","Sharavathi","nadi","inda","256","metre","uchi","inda","neeru","biDuttade",",","thumba","adbhuta","."],"correctAnswer":"Jog Falls nodidaaga manassu tumbitu — Sharavathi nadi inda 256 metre uchi inda neeru biDuttade , thumba adbhuta ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Karavali means?","options":["the coastal zone of Karnataka","Western Ghats","Deccan plateau","river belt"],"correctAnswer":"the coastal zone of Karnataka"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000072',1,'APPROVED','PUBLISHED',
'{"objectives":["Make and respond to suggestions in Kannada","Use hogona, maadona, try maaDona for suggestions","Accept, decline, or counter-propose suggestions"],"explanation":{"intro":"Making suggestions vocabulary covers how to propose an idea, how to accept or decline politely, and how to offer a counter-proposal — key for planning activities with friends and colleagues.","culturalNote":"Suggestion culture in Karnataka: suggestions in Karnataka are often made indirectly and politely — directness depends on relationship. Close friends: very direct — ''naaLe cinema hogi bidi!'' (let''s just go to the cinema tomorrow!). Colleagues: more polite — ''naaLe oota jote maaDalaam aa?'' (shall we eat together tomorrow?). Suggestions to elders: indirect — ''nimma ishta — naaLe X maaDalikante hoguvudaa?'' (if you wish — shall we go for X tomorrow?). Family plans: family decisions in Karnataka are often collective — suggesting then getting consensus (''ellaariguu okka aagutte''a? = is it okay for everyone?). Refusing a suggestion: direct refusal is softened — ''sari aagatta, naaLe try maaDona'' (okay let''s try tomorrow) or ''naakke kashtavaagutte'' (it''s difficult for me). Food suggestions: ''naaLe MTR ge hogona'' (let''s go to MTR tomorrow!) or ''majjige huli maaDona'' (let''s make majjige huli!) — food plans are very natural suggestion topics."},"examples":[{"sentence":"Naalave namma team jote lunch ge hogona — naakke MTR tookoLuvudu idea ide anta anisuttide.","english":"Tomorrow let''s go for lunch with our team — I have an idea of going to MTR, what do you think."},{"sentence":"Cinema hogona anta heLide — aadare naakke naale kashtavaagutte, munde saari try maaDona.","english":"I said let''s go to the cinema — but it is difficult for me tomorrow, let''s try next time."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can make, accept, decline, and counter-propose suggestions in Kannada."}}',
'{"items":[{"word":"hogona","translation":"let''s go (suggestion — hortative)","transliteration":"hogona","pronunciation":"HO-go-na","example":"cinema ge hogona"},{"word":"maaDona","translation":"let''s do (suggestion — hortative)","transliteration":"maaDona","pronunciation":"MAA-do-na","example":"oota maaDona"},{"word":"idea ide","translation":"I have an idea / there is an idea","transliteration":"idea ide","pronunciation":"ai-DEE-a I-de","example":"naakke idea ide"},{"word":"munde saari","translation":"next time","transliteration":"munde saari","pronunciation":"MUN-de SAA-ri","example":"munde saari hogona"},{"word":"okka aagutte","translation":"it is okay/agreed (for everyone)","transliteration":"okka aagutte","pronunciation":"OK-ka aa-GUT-te","example":"ellaariguu okka aagutte"},{"word":"counter-proposal","translation":"counter-proposal (offering alternative)","transliteration":"counter-proposal","pronunciation":"KAWN-ter pro-PO-zal","example":"counter-proposal koDuttini"}]}',
'{"title":"Making suggestions in Kannada — hogona/maaDona (hortative)","pattern":"X hogona = let''s go to X. X maaDona = let''s do X. Asking for agreement: X maaDona — okka aagutte? (let''s do X — is it okay?). Accepting: howdu, hogona! (yes, let''s go!). Declining: naakke kashtavaagutte (it''s difficult for me), naale possible agalla (tomorrow not possible). Counter-proposal: X aadare, Y try maaDona (if not X, let''s try Y). Next time: munde saari X maaDona (let''s do X next time).","explanation":"Hortative (suggestion) mood in Kannada: -ona suffix = let''s. Hogona (let''s go), maaDona (let''s do), tinNona (let''s eat), nodona (let''s see), keLona (let''s listen), oota maaDona (let''s eat/cook together). Formal: -oma suffix (slightly more formal): hogoma (let us go). Question form: X hogona aa? (shall we go to X? — the ''aa'' makes it a yes/no question). Gentle suggestion: X maaDuvudu hege aadutte? (how about doing X?). Enthusiastic acceptance: super idea! Hogona! (super idea! Let''s go!). Partial acceptance: sari, aadare X aadare better (okay, but if X it would be better — counter-suggestion). Firm decline: naakke today possible agalla, sorry (not possible for me today, sorry).","examples":[{"sentence":"Viikenda Coorg ge hogona — thaNNage iru, coffee kudiyona, trek maaDona — super plan alla vaa?","english":"This weekend let''s go to Coorg — stay cool, drink coffee, do trek — isn''t it a super plan?"},{"sentence":"Naakke viikenda possible agalla — aadare munde saari definitely hogona, promise!","english":"For me the weekend is not possible — but next time let''s definitely go, promise!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"hogona means?","options":["let''s go (suggestion — hortative)","I will go","they went","let''s not go"],"correctAnswer":"let''s go (suggestion — hortative)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tomorrow let''s go for lunch with our team — I have an idea of going to MTR, what do you think.","options":["Naalave namma team jote lunch ge hogona — naakke MTR tookoLuvudu idea ide anta anisuttide.","Ivaththu namma team jote lunch ge hogona — naakke MTR tookoLuvudu idea ide anta anisuttide.","Naalave namma team jote dinner ge hogona — naakke MTR tookoLuvudu idea ide anta anisuttide.","Naalave nimma team jote lunch ge hogona — naakke MTR tookoLuvudu idea ide anta anisuttide."],"correctAnswer":"Naalave namma team jote lunch ge hogona — naakke MTR tookoLuvudu idea ide anta anisuttide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naakke viikenda possible agalla — aadare ___ definitely hogona, promise!","options":["munde saari","ivaththu","naale","pichle"],"correctAnswer":"munde saari"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This weekend let''s go to Coorg — stay cool, drink coffee, do trek — isn''t it a super plan?","wordBankItems":["Viikenda","Coorg","ge","hogona","—","thaNNage","iru",",","coffee","kudiyona",",","trek","maaDona","—","super","plan","alla","vaa","?"],"correctAnswer":"Viikenda Coorg ge hogona — thaNNage iru , coffee kudiyona , trek maaDona — super plan alla vaa ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"munde saari means?","options":["next time","last time","this time","every time"],"correctAnswer":"next time"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000073',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about hobbies and passions in depth in Kannada","Describe why you love a hobby","Use yaakenendare and asakti vocabulary for passion"],"explanation":{"intro":"Hobbies and passions vocabulary covers not just naming hobbies but explaining why you love them — motivation, meaning, and depth of engagement.","culturalNote":"Hobby culture in Karnataka: (1) Reading: Kannada literature reading is a valued hobby — Kuvempu Sahitya, short stories, poetry. Kannada Pusthaka Pradhikara (Karnataka Sahitya Academy) organizes book fairs. (2) Music: learning to play veena (classical instrument), flute, or harmonium is common. Carnatic vocal music (shaastriya sangeeta) is a popular hobby especially in traditional families. (3) Gardening: ''tota'' (garden) — growing vegetables and flowers is a common hobby for older Bengaluru residents. Terrace gardens are increasingly popular in apartment culture. (4) Photography: landscape and wildlife photography is a growing hobby — Western Ghats offer amazing subjects. (5) Cricket: playing cricket in apartment complexes, parks — weekend ritual. (6) Cooking: many men and women in urban Bengaluru have taken up cooking as a hobby. (7) Yoga: practiced as a hobby and spiritual pursuit. (8) Trekking: Karnataka''s hills (Nandi Hills, Mullayanagiri, Kumara Parvata) attract trekkers."},"examples":[{"sentence":"Nanna hobby photography — yaakenendare namma Karnataka praakRitika soundarya camera inda capture maaDuvudu naakke thumba khushi koDutte.","english":"My hobby is photography — because capturing Karnataka''s natural beauty through a camera gives me a lot of joy."},{"sentence":"Naanu Carnatic music kalikuttiddeeni — ishtavaadadu yaakenendare idu namma sanskriti haagu naakke inner peace koDutte.","english":"I am learning Carnatic music — I love it because it is our culture and it gives me inner peace."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about my hobbies and explain why I am passionate about them in Kannada."}}',
'{"items":[{"word":"hobby","translation":"hobby (English — universally used)","transliteration":"hobby","pronunciation":"HOB-i","example":"nanna hobby"},{"word":"asakti","translation":"interest/passion/fascination","transliteration":"asakti","pronunciation":"aa-SAK-ti","example":"thumba asakti"},{"word":"capture maaDuvudu","translation":"to capture (photography)","transliteration":"capture maaDuvudu","pronunciation":"KAP-cher MAA-du-vu-du","example":"photo capture maaDide"},{"word":"inner peace","translation":"inner peace (English — increasingly used in hobby/wellness context)","transliteration":"inner peace","pronunciation":"IN-ner PEES","example":"inner peace koDutte"},{"word":"sanskriti","translation":"culture/tradition (deeply rooted culture)","transliteration":"sanskriti","pronunciation":"SAN-skri-ti","example":"namma sanskriti"},{"word":"koushalya","translation":"skill/expertise (developed through a hobby)","transliteration":"koushalya","pronunciation":"kaw-SHAL-ya","example":"koushalya beLesuttide"}]}',
'{"title":"Hobbies and passions in Kannada — asakti","pattern":"Nanna hobby X = my hobby is X. Naakke X alli thumba asakti ide = I have a lot of interest in X. X ishtavaadadu yaakenendare Y = I love X because Y. X maaDuvudu naakke khushi koDutte = doing X gives me joy. X kalikuttiddeeni = I am learning X (ongoing).","explanation":"Hobby vocabulary in Kannada: hobby (hobby — English), asakti (interest/passion), iShTa (liked — strong preference: naakke X thumba iShTa = I really like X). Expressing love for a hobby: naakke X alli maana hogide (my mind is absorbed in X — ''maana hogide'' = mind has gone = deeply absorbed), X maaDuvudu naakke haayenisuttade (doing X makes me feel peaceful). Learning a hobby: X kalikuttiddeeni (I am learning X), X kali shuru maadide (I started learning X). Progress: thumba oLLeyaagi kaaLuttiddeeni (I am doing it well — progressing), inna kaLiyabeku (I still need to learn). Teaching: X kalisi koDuttaare (they teach X). Why a hobby matters: X inda naanu relax aagutte (through X I relax), X inda naanu khushi aagutte (through X I become happy).","examples":[{"sentence":"Naanu trekking maaDuvudu thumba ishtavaadadu — Western Ghats betta hodidaaga namma praakRitika soundarya kaNNalle noduttide.","english":"I love trekking very much — when I go to Western Ghats hills, our natural beauty is visible to the eyes."},{"sentence":"Naanu music kali shuru maadide — Carnatic music alli koushalya beLesikonDiddini haagu naakke thumba santosha koDutte.","english":"I started learning music — I am developing skills in Carnatic music and it gives me a lot of happiness."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"asakti means?","options":["interest/passion/fascination","hobby","skill","culture"],"correctAnswer":"interest/passion/fascination"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My hobby is photography — because capturing Karnataka''s natural beauty through a camera gives me a lot of joy.","options":["Nanna hobby photography — yaakenendare namma Karnataka praakRitika soundarya camera inda capture maaDuvudu naakke thumba khushi koDutte.","Nanna hobby photography — yaakenendare namma Karnataka praakRitika soundarya camera inda capture maaDuvudu avakke thumba khushi koDutte.","Nanna hobby trekking — yaakenendare namma Karnataka praakRitika soundarya camera inda capture maaDuvudu naakke thumba khushi koDutte.","Nanna hobby photography — yaakenendare namma Karnataka praakRitika soundarya camera inda capture maaDuvudu naakke thakku khushi koDutte."],"correctAnswer":"Nanna hobby photography — yaakenendare namma Karnataka praakRitika soundarya camera inda capture maaDuvudu naakke thumba khushi koDutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu music kali shuru maadide — Carnatic music alli ___ beLesikonDiddini haagu naakke thumba santosha koDutte.","options":["koushalya","sanskriti","asakti","hobby"],"correctAnswer":"koushalya"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I love trekking very much — when I go to Western Ghats hills, our natural beauty is visible to the eyes.","wordBankItems":["Naanu","trekking","maaDuvudu","thumba","ishtavaadadu","—","Western","Ghats","betta","hodidaaga","namma","praakRitika","soundarya","kaNNalle","noduttide","."],"correctAnswer":"Naanu trekking maaDuvudu thumba ishtavaadadu — Western Ghats betta hodidaaga namma praakRitika soundarya kaNNalle noduttide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"koushalya means?","options":["skill/expertise","culture","hobby","interest"],"correctAnswer":"skill/expertise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000074',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss education and learning in Kannada","Name educational stages and institutions","Talk about exam pressure and academic goals"],"explanation":{"intro":"Education vocabulary covers the Karnataka education system, academic vocabulary, discussing studies, and talking about learning journeys.","culturalNote":"Education culture in Karnataka: (1) Education is extremely valued in Karnataka — especially in the Brahmin, Lingayat, and Vokkaliga communities. (2) IIT-JEE and NEET: entrance exams are a cultural phenomenon — families plan years ahead. Ramaiah PU College, Deeksha, BASE — famous Bengaluru coaching institutes. (3) VTU (Visvesvaraya Technological University) — the main technical university in Karnataka. Karnataka has over 200 engineering colleges. (4) Bangalore University, Mysore University — major universities. (5) IISc (Indian Institute of Science) in Bengaluru — India''s premier research institution. (6) Medium of instruction: government schools (sarkaari shaale) — Kannada medium; private schools — English medium mostly. Language policy debates: Kannada medium education is a political and cultural issue. (7) Competitive exams: KAS (Karnataka Administrative Service), UPSC, bank exams, Group C&D — millions sit for government job exams every year. (8) First-generation learners: many rural Karnataka students are first-generation college students — a source of great family pride. (9) Dropout rates: rural Karnataka has work to do on improving secondary completion rates for girls."},"examples":[{"sentence":"Nanna tamma NEET exam ge prepare maaDuttidaane — daily 10-12 gante oodi kaliyuttaane, thumba kelsa.","english":"My younger brother is preparing for the NEET exam — he is studying 10-12 hours daily, very hard work."},{"sentence":"Naanu Bengaluru University inda degree maadide — alli kalli nanna astitva bekeeti aagiutte.","english":"I completed my degree from Bengaluru University — I feel my identity was built there."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss education, academic goals, and the Karnataka education system in Kannada."}}',
'{"items":[{"word":"shaale","translation":"school","transliteration":"shaale","pronunciation":"SHAA-le","example":"nanna shaale"},{"word":"college","translation":"college/university (English used)","transliteration":"college","pronunciation":"KOL-ij","example":"college alli"},{"word":"pariksha","translation":"exam/examination","transliteration":"pariksha","pronunciation":"pa-RIK-sha","example":"pariksha baruttade"},{"word":"degree","translation":"university degree (English used)","transliteration":"degree","pronunciation":"di-GREE","example":"degree maadide"},{"word":"competitive exam","translation":"competitive exam (government/entrance)","transliteration":"competitive exam","pronunciation":"kom-PET-i-tiv ig-ZAM","example":"KAS competitive exam"},{"word":"first generation","translation":"first-generation (learner — first in family to study)","transliteration":"first generation","pronunciation":"furst JEN-er-ay-shen","example":"first generation student"}]}',
'{"title":"Education vocabulary in Kannada","pattern":"X pariksha ge prepare maaDuttiddeeni = I am preparing for X exam. X inda degree maadide = I completed degree from X. X shaale/college ge hogutte = I go to X school/college. Studying: oduttiddeeni/kalikuttiddeeni (I am reading/learning — ongoing). Exam result: pass aadini (I passed), fail aadini (I failed — direct), result channagi bande (good result came).","explanation":"Education vocabulary in Kannada: shaale (school), college (college — English), vishvavidyaalaya (university — formal Kannada), pariksha (exam), result (result — English), degree (degree — English), marks (marks — English), grade (grade — English). Levels: primary shaale (primary school), high school (high school), PU college (pre-university), degree college (undergraduate), post-graduation (PG). Subjects: mathematics (mathematics/ganita), science (science/shaastra), language (bhaashe), history (itihasa), geography (bhuugola). Study verbs: oduvudu (to read/study), kalikuvudu (to learn), prepare maaDuvudu (to prepare — exam), pass aaguvudu (to pass), fail aaguvudu (to fail). Academic pressure: exam pressure (exam pressure — thumba pressure ide), tension ide (there is tension), parvaagilla (it''s okay — reassuring phrase from elders).","examples":[{"sentence":"Nanna akka first generation college student aagiutte — avara family alli degree idU mudal baaridaLu — thumba proud aagutte.","english":"My elder sister was the first-generation college student — she was the first in her family to get a degree — I feel very proud."},{"sentence":"KAS exam thumba kashtada competitive exam — laksha keLa prepare maaDuttaare, aadare seats saavira maatraade.","english":"KAS exam is a very tough competitive exam — lakhs prepare, but seats are only in thousands."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"pariksha means?","options":["exam/examination","school","college","result"],"correctAnswer":"exam/examination"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My younger brother is preparing for the NEET exam — he is studying 10-12 hours daily, very hard work.","options":["Nanna tamma NEET exam ge prepare maaDuttidaane — daily 10-12 gante oodi kaliyuttaane, thumba kelsa.","Nanna anna NEET exam ge prepare maaDuttidaane — daily 10-12 gante oodi kaliyuttaane, thumba kelsa.","Nanna tamma NEET exam ge prepare maaDuttidaane — daily 8-10 gante oodi kaliyuttaane, thumba kelsa.","Nanna tamma KAS exam ge prepare maaDuttidaane — daily 10-12 gante oodi kaliyuttaane, thumba kelsa."],"correctAnswer":"Nanna tamma NEET exam ge prepare maaDuttidaane — daily 10-12 gante oodi kaliyuttaane, thumba kelsa."},{"id":"ex3","type":"FILL_IN_BLANK","question":"KAS exam thumba kashtada competitive exam — laksha keLa prepare maaDuttaare, aadare seats ___ maatraade.","options":["saavira","haththu","nooru","lakh"],"correctAnswer":"saavira"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My elder sister was the first-generation college student — she was the first in her family to get a degree — I feel very proud.","wordBankItems":["Nanna","akka","first","generation","college","student","aagiutte","—","avara","family","alli","degree","idU","mudal","baaridaLu","—","thumba","proud","aagutte","."],"correctAnswer":"Nanna akka first generation college student aagiutte — avara family alli degree idU mudal baaridaLu — thumba proud aagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"parvaagilla means?","options":["it''s okay (reassuring phrase)","not possible","no problem","don''t worry"],"correctAnswer":"it''s okay (reassuring phrase)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000075',1,'APPROVED','PUBLISHED',
'{"objectives":["Express gratitude and appreciation in Kannada","Use dhanyavaadagaLu, upakaaravagutte vocabulary","Give genuine compliments and heartfelt thanks"],"explanation":{"intro":"Gratitude and appreciation vocabulary covers a range of ways to thank someone — from casual to formal — and how to give genuine compliments.","culturalNote":"Gratitude culture in Karnataka: (1) ''Dhanyavaadagaalu'' is the formal thank you in Kannada — often seen on shop signs, notices. In daily speech, ''thanks'' (English) or ''thanks ide'' is very common among youth. (2) Compliments: Kannadigas can be indirect with compliments — a compliment is often embedded in a statement rather than given directly. (3) Host appreciation: guests always compliment the host''s cooking — ''oota thumba channagi aagiutte'' (the food turned out very well) is a critical social phrase. (4) Service gratitude: at hotels and service points, expressing thanks is becoming more common — influenced by corporate culture. (5) Religious gratitude: ''devara dayyaadi'' (by God''s grace), ''devaru oLLeyadu maaDiddaare'' (God has done good) — gratitude expressed to God is very natural. (6) Career gratitude: thanking a mentor or manager — ''nimma guidance illadidare ee position ge baruttiddilla'' (without your guidance I wouldn''t have reached this position). (7) The Kannada character: hospitality (athithi devo bhava = guest is God) means the host rarely accepts thanks — ''enu maaDalla'' (what did I do — nothing much) is a typical modest response to thanks."},"examples":[{"sentence":"Nimma sahaaya inda naanu ee project poorthi maaDa shakyavaagiutte — thumba dhanyavaadagaLu!","english":"Because of your help I was able to complete this project — many thanks!"},{"sentence":"Nimma cooking thumba channagi aagiutte — ee biryani life alli tinNda best biryani!","english":"Your cooking turned out very well — this biryani is the best biryani I have eaten in life!"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express genuine gratitude and give heartfelt compliments in Kannada."}}',
'{"items":[{"word":"dhanyavaadagaLu","translation":"thank you (formal — plural of dhanyavaada = thanks)","transliteration":"dhanyavaadagaLu","pronunciation":"dha-nya-VAA-da-ga-Lu","example":"thumba dhanyavaadagaLu"},{"word":"upakaaravagutte","translation":"it is a favor/I am grateful (naakke thumba upakaaravagutte = I am very grateful)","transliteration":"upakaaravagutte","pronunciation":"u-pa-KAA-ra-va-gut-te","example":"naakke thumba upakaaravagutte"},{"word":"enu maaDalla","translation":"what did I do (modest response to thanks)","transliteration":"enu maaDalla","pronunciation":"E-nu MAA-Dal-la","example":"enu maaDalla — parvaagilla"},{"word":"guidance","translation":"guidance/mentoring (English — professional context)","transliteration":"guidance","pronunciation":"GAI-dens","example":"nimma guidance"},{"word":"shakyavaagiutte","translation":"it became possible (X maaDa shakyavaagiutte = it became possible to do X)","transliteration":"shakyavaagiutte","pronunciation":"shak-ya-VAA-gi-ut-te","example":"poorthi maaDa shakyavaagiutte"},{"word":"life alli","translation":"in (my) life — used for emphasis (life alli tinNda best = best eaten in life)","transliteration":"life alli","pronunciation":"laif AL-li","example":"life alli tinNda best"}]}',
'{"title":"Dhanyavaadagaalu — gratitude and appreciation in Kannada","pattern":"Nimma X inda Y shakyavaagiutte = Because of your X, Y became possible. Thumba dhanyavaadagaLu = many thanks (formal). Naakke thumba upakaaravagutte = I am very grateful. Compliment: X thumba channagi aagiutte = X turned out very well. Life-best compliment: ee X life alli Y da best X (this X is the best X of Y I''ve had in life — e.g. best biryani).","explanation":"Gratitude expressions in Kannada: casual: thanks (English), swalpa thanks (a small thanks — humble). Standard: dhanyavaadagaLu (formal thanks). Grateful: naakke thumba upakaaravagutte (I am very grateful). Deep gratitude: nimma sahaaya ellaa dinaruu mareyalla (I will never forget your help every day). Modest response to thanks: enu maaDalla (what did I do — nothing much), parvaagilla (it''s nothing), swamy kaaryavanthe maaDide (I just did God''s work — very humble). Compliment food: thumba channagi aagutte (very tasty), oota supervaagi aagiutte (food is super). Compliment work: nimma kaela thumba channaagi ide (your work is very good). Compliment appearance: nimma sari thumba channa ide (your saree is very beautiful). Professional thanks: nimma guidance inda naanu X maaDa shakyavaadini (with your guidance I was able to do X).","examples":[{"sentence":"Nanna interview alli nimma support thumba muhtvadaagitu — naakke thumba dhanyavaadagaLu haagu upakaaravagutte.","english":"In my interview your support was very important — many thanks to you and I am very grateful."},{"sentence":"Ee hosa mane thumba channagide — nimma taste thumba oLLeyadhu anta ellaariguu anisuttide.","english":"This new house is very beautiful — everyone feels that your taste is very good."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"dhanyavaadagaLu means?","options":["thank you (formal)","you are welcome","please","I am sorry"],"correctAnswer":"thank you (formal)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Because of your help I was able to complete this project — many thanks!","options":["Nimma sahaaya inda naanu ee project poorthi maaDa shakyavaagiutte — thumba dhanyavaadagaLu!","Nimma sahaaya inda naanu ee project shuru maaDa shakyavaagiutte — thumba dhanyavaadagaLu!","Nanna sahaaya inda naanu ee project poorthi maaDa shakyavaagiutte — thumba dhanyavaadagaLu!","Nimma sahaaya inda naanu ee project poorthi maaDa shakyavaagiutte — swalpav dhanyavaadagaLu!"],"correctAnswer":"Nimma sahaaya inda naanu ee project poorthi maaDa shakyavaagiutte — thumba dhanyavaadagaLu!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna interview alli nimma support thumba muhtvadaagitu — naakke thumba dhanyavaadagaLu haagu ___ .","options":["upakaaravagutte","sahmatagalla","asakti ide","okka aagutte"],"correctAnswer":"upakaaravagutte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Your cooking turned out very well — this biryani is the best biryani I have eaten in life!","wordBankItems":["Nimma","cooking","thumba","channagi","aagiutte","—","ee","biryani","life","alli","tinNda","best","biryani","!"],"correctAnswer":"Nimma cooking thumba channagi aagiutte — ee biryani life alli tinNda best biryani !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"enu maaDalla means?","options":["what did I do (modest response to thanks)","I didn''t do anything wrong","I can''t do it","what should I do"],"correctAnswer":"what did I do (modest response to thanks)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000076',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about future goals and ambitions in Kannada","Use guri, bhavishya, and aspiration vocabulary","Describe 5-year plans and career ambitions"],"explanation":{"intro":"Future goals vocabulary covers how to describe your ambitions, career path, personal goals, and vision for the future in Kannada.","culturalNote":"Ambition culture in Karnataka: (1) IT career: the prototypical Bengaluru ambition — ''IT company alli senior engineer aagabeku'' (I want to become a senior engineer in an IT company). Many IT professionals aspire to move to senior roles, management, or start their own company. (2) Startup culture: Bengaluru''s startup ecosystem — many IT professionals dream of founding a startup. (3) Government service: KAS, IAS, IPS — civil service ambition is strong. Prestige and stability. (4) Academia: research at IISc, IIT, or abroad — academic ambition in science and engineering. (5) Farming with dignity: younger generation of Karnataka farmers aspire to modern, organic farming with dignity — not just survival. (6) Social work: NGO sector — working for Karnataka''s rural development is an aspiration for some. (7) Arts: Kannada film direction, acting, writing — creative ambitions. (8) NRI dream: many Bengaluru IT professionals have a goal of working abroad (USA, UK, Canada) for a few years. (9) Home ownership: owning a home (mane kaTTuvudu or flat konDuvudu) is a near-universal ambition for working Bengaluru residents."},"examples":[{"sentence":"Nanna guri 5 varsha alli nanna company shuru maaDuvudu — ivaththu IT alli kaela maaDuttiddeeni, experience beLeyuttiddeeni.","english":"My goal is to start my own company in 5 years — today I am working in IT, I am growing my experience."},{"sentence":"Naanu abroad hogi 2-3 varsha kaela maaDi nantara Bengaluru ge mele bandu startup found maaDabeku anta think maaDuttiddeeni.","english":"I am thinking of going abroad, working 2-3 years, and then coming back to Bengaluru to found a startup."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about future goals, ambitions, and career plans in Kannada."}}',
'{"items":[{"word":"guri","translation":"goal/aim/target","transliteration":"guri","pronunciation":"GU-ri","example":"nanna guri"},{"word":"bhavishya","translation":"future","transliteration":"bhavishya","pronunciation":"bha-VISH-ya","example":"bhavishya plan"},{"word":"startup","translation":"startup (English — Bengaluru context)","transliteration":"startup","pronunciation":"STAART-up","example":"startup found maaDabeku"},{"word":"experience","translation":"experience (professional)","transliteration":"experience","pronunciation":"eks-PEER-yen-s","example":"experience beLeyuttiddeeni"},{"word":"abroad","translation":"abroad/overseas (English — very common)","transliteration":"abroad","pronunciation":"a-BRAWD","example":"abroad hogi"},{"word":"found maaDuvudu","translation":"to found/establish (company, organization)","transliteration":"found maaDuvudu","pronunciation":"fawnd MAA-du-vu-du","example":"company found maaDabeku"}]}',
'{"title":"Future goals in Kannada — guri haagu bhavishya","pattern":"Nanna guri X maaDuvudu = My goal is to do X. X varsha alli X maaDabeku = I want to do X in X years. Naanu X beLeyuttiddeeni = I am growing/building X (skills, experience). X maaDi nantara Y maaDabeku = after doing X I want to do Y. Ambition chain: experience beLesi, startup shuru maaDi, namma deshakke yogadaana koDuttini (grow experience, start startup, contribute to our country).","explanation":"Future goals vocabulary in Kannada: guri (goal/aim), bhavishya (future), svapna (dream), aakaanksha (aspiration). Career goals: IT alli grow aaguvudu (grow in IT), management ge hoguvudu (go to management), startup found maaDuvudu (found startup), government kaela maaDuvudu (work for government). Personal goals: mane kaTTuvudu (build a house), flat konDuvudu (buy a flat), abroad hoguvudu (go abroad), family paripaalisuvudu (take care of family). Timeline: ee varsha (this year), 2-3 varsha alli (in 2-3 years), 5 varsha alli (in 5 years), hattu varsha alli (in 10 years). Progress tracking: X maaDide (I did X — milestone done), X baakie ide (X is still remaining). Motivation: ee guri saadsuvudu naakke thumba muhtvada (achieving this goal is very important to me).","examples":[{"sentence":"Nanna 5 varsha plan: prathama senior engineer aaguvudu, nantara management training, kaDeyalli nanna own startup shuru maaDuvudu.","english":"My 5-year plan: first become a senior engineer, then management training, finally start my own startup."},{"sentence":"Naakke guri ide Karnataka inda navin bhaashe kalikuvudu — Kannada nantara Tamil kaliyabeku anta nambuttiddeeni.","english":"I have a goal of learning a new language from Karnataka — after Kannada I believe I should learn Tamil."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"guri means?","options":["goal/aim/target","dream","aspiration","plan"],"correctAnswer":"goal/aim/target"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My goal is to start my own company in 5 years — today I am working in IT, I am growing my experience.","options":["Nanna guri 5 varsha alli nanna company shuru maaDuvudu — ivaththu IT alli kaela maaDuttiddeeni, experience beLeyuttiddeeni.","Nanna guri 10 varsha alli nanna company shuru maaDuvudu — ivaththu IT alli kaela maaDuttiddeeni, experience beLeyuttiddeeni.","Nanna guri 5 varsha alli nanna company shuru maaDuvudu — naale IT alli kaela maaDuttiddeeni, experience beLeyuttiddeeni.","Avana guri 5 varsha alli avana company shuru maaDuvudu — ivaththu IT alli kaela maaDuttaane, experience beLeyuttaane."],"correctAnswer":"Nanna guri 5 varsha alli nanna company shuru maaDuvudu — ivaththu IT alli kaela maaDuttiddeeni, experience beLeyuttiddeeni."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna 5 varsha plan: prathama senior engineer aaguvudu, nantara management training, kaDeyalli nanna own ___ shuru maaDuvudu.","options":["startup","shaale","college","company"],"correctAnswer":"startup"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My 5-year plan: first become a senior engineer, then management training, finally start my own startup.","wordBankItems":["Nanna","5","varsha","plan",":","|","prathama","senior","engineer","aaguvudu",",","nantara","management","training",",","kaDeyalli","nanna","own","startup","shuru","maaDuvudu","."],"correctAnswer":"Nanna 5 varsha plan : | prathama senior engineer aaguvudu , nantara management training , kaDeyalli nanna own startup shuru maaDuvudu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"bhavishya means?","options":["future","past","present","ambition"],"correctAnswer":"future"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000077',1,'APPROVED','PUBLISHED',
'{"objectives":["Review all A2 grammar patterns covered in lessons 111-118","Consolidate complex sentence patterns","Practice chaining multiple A2 patterns in one sentence"],"explanation":{"intro":"A2 grammar consolidation reviews the grammar patterns from this batch — participial phrases, hortative mood, extended family, emotional vocabulary, and future goals — and practices chaining them.","culturalNote":"Consolidation in Kannada learning: language learners often feel a breakthrough moment (''click aagutte'' — it clicks) when they can combine multiple patterns in a single natural sentence. In Kannada, this often happens when: (1) You can use hortative (-ona) naturally in conversation. (2) You can explain WHY you like something (yaakenendare). (3) You can use time markers naturally (hinde, abhi, munde). (4) You start dreaming in Kannada fragments. (5) You understand the jokes in Kannada films without subtitles. The journey: learning a Dravidian language as an adult speaker of a non-Dravidian language is genuinely challenging. Encourage yourself: neevu thumba oLLeyaagi kalikuttiri (you are learning very well). Consistency is key — daily 15-minute practice beats weekly 3-hour sessions."},"examples":[{"sentence":"Nanna guri enu anta heLidaaga — naanu clearly heLuttini ki nanna startup shuru maaDabeku, yaakenendare naakke technology haagu business eraDuu alli asakti ide.","english":"When asked what my goal is — I say clearly that I want to start my startup, because I have interest in both technology and business."},{"sentence":"Hinde naakke bhaashe kalivudu kashtavaagitu, abhi thumba easy aagutte — practice inda bandaavaNi aagutte!","english":"Earlier learning the language used to be difficult, now it is much easier — change comes through practice!"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I can combine multiple A2 grammar patterns in natural Kannada sentences."}}',
'{"items":[{"word":"click aagutte","translation":"it clicks (understanding suddenly arrives)","transliteration":"click aagutte","pronunciation":"klik aa-GUT-te","example":"Kannada click aagutte"},{"word":"breakthrough","translation":"breakthrough (moment of clarity in learning)","transliteration":"breakthrough","pronunciation":"BRAYK-throo","example":"language breakthrough"},{"word":"chaining","translation":"chaining (connecting multiple grammar patterns)","transliteration":"chaining","pronunciation":"CHAYN-ing","example":"patterns chaining"},{"word":"consolidation","translation":"consolidation (bringing together what was learned)","transliteration":"consolidation","pronunciation":"kon-sol-i-DAY-shen","example":"grammar consolidation"},{"word":"natural","translation":"natural (speaking naturally — without thinking)","transliteration":"natural","pronunciation":"NACH-er-al","example":"natural aagiutte"},{"word":"consistent","translation":"consistent (practice every day)","transliteration":"consistent","pronunciation":"kon-SIS-tent","example":"consistent practice"}]}',
'{"title":"A2 grammar consolidation — chaining patterns","pattern":"Complex sentences combining: (1) reported speech (anta heLida), (2) conditional (-are/-dare), (3) change (hinde...abhi), (4) wish (aagabeku anta), (5) possibility (bahudu), (6) instructions (prathama...nantara), (7) apology (kshamisi), (8) strong opinion (dRiDha abipraaya), (9) hortative (-ona). Practice: chain 2-3 patterns in one sentence.","explanation":"A2 grammar patterns consolidated: (1) Reported speech: X anta heLida / heLidaare ki X. (2) Conditionals: X -are/-dare Y. (3) Change: hinde X aagiutte, abhi Y. (4) Wishes: X aagabeku anta ishtavagutte. (5) Descriptions: haakkonDu, hattikkonDu participials. (6) Possibility: bahudu, shaayada, nishchayavaagi. (7) Instructions: prathama X, nantara Y, kaDeyalli Z. (8) Apology: kshamisi, tappu. (9) Suggestions: X hogona, X maaDona. (10) Reasons: yaakenendare. (11) Future goals: guri, bhavishya. Chaining example: Naanu startup shuru maaDabeku anta guri ide, yaakenendare technology alli asakti ide, hinde experience kammi aagiutte aadare abhi beLeyuttiddeeni (I have a goal to start a startup, because I have interest in technology, earlier experience was less but now I am growing it — 4 patterns in one sentence!).","examples":[{"sentence":"Avaru heLidaare ki naale beLigge bega ezhuttidare traffic kammi ide haagu bega office ge siguttade — naanu try maaDuttini anta heLide.","english":"They said that if you get up early tomorrow morning there is less traffic and the office is reached quickly — I said I will try."},{"sentence":"Nanna amma heLtaLe ki tarashari yoga maaDi, healthy oota tini haagu raatruu bega malagoodu — idu follow maaDidare channagi aagiutte anta clear ide.","english":"My mother says to do yoga regularly, eat healthy food and sleep early at night — it is clear that if this is followed things will be good."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"click aagutte means in language learning?","options":["it clicks (understanding suddenly arrives)","it is confusing","it is difficult","it is easy"],"correctAnswer":"it clicks (understanding suddenly arrives)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"They said that if you get up early tomorrow morning there is less traffic and the office is reached quickly.","options":["Avaru heLidaare ki naale beLigge bega ezhuttidare traffic kammi ide haagu bega office ge siguttade.","Avaru heLidaare ki inja beLigge bega ezhuttidare traffic kammi ide haagu bega office ge siguttade.","Avaru heLidaare ki naale saayankala bega ezhuttidare traffic kammi ide haagu bega office ge siguttade.","Avanu heLidaane ki naale beLigge bega ezhuttidare traffic kammi ide haagu bega office ge siguttade."],"correctAnswer":"Avaru heLidaare ki naale beLigge bega ezhuttidare traffic kammi ide haagu bega office ge siguttade."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna amma heLtaLe ki tarashari yoga maaDi, healthy oota tini haagu raatruu bega ___ — idu follow maaDidare channagi aagutte.","options":["malagoodu","ezhuttidu","kaela maaDu","hoguvudu"],"correctAnswer":"malagoodu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have a goal to start a startup, because I have interest in technology, earlier experience was less but now I am growing it.","wordBankItems":["Naanu","startup","shuru","maaDabeku","anta","guri","ide",",","yaakenendare","technology","alli","asakti","ide",",","hinde","experience","kammi","aagiutte","aadare","abhi","beLeyuttiddeeni","."],"correctAnswer":"Naanu startup shuru maaDabeku anta guri ide , yaakenendare technology alli asakti ide , hinde experience kammi aagiutte aadare abhi beLeyuttiddeeni ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"The -ona suffix in Kannada creates what kind of form?","options":["hortative (let''s...) — suggestion","imperative (do!)","past tense","future tense"],"correctAnswer":"hortative (let''s...) — suggestion"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000078',1,'APPROVED','PUBLISHED',
'{"objectives":["Celebrate completing 120 Kannada lessons","Review the full journey from A1 to A2","Set intentions for continued Kannada learning"],"explanation":{"intro":"Completing 120 Kannada lessons is a major achievement! You have built a solid foundation across A1 and A2 — this final lesson celebrates that journey and sets you up for what comes next.","culturalNote":"Your Kannada journey — what you have achieved: You began with ''Namaskara'' and ''Hegidiri'' and have now mastered: A1 skills (Lessons 1-90): Greetings, numbers, family, food, time, directions, shopping, transport, health, Karnataka culture (Yakshagana, Hampi, RCB, filter kaapi, bisi bele bath), three tenses, negation. Early A2 skills (Lessons 91-120): Reported speech, conditionals, changes over time, wishes, complex descriptions, possibility, instructions, regret/apology, work vocabulary, polite disagreement, weekend activities, health/lifestyle, festivals (Dasara/Ugaadi/Rajyotsava), news/current affairs, travel experiences, strong opinions, shopping/bargaining, problem-solving, family depth, emotions, natural beauty (Western Ghats/Karavali), suggestions, hobbies, education, gratitude, future goals. Karnataka cultural knowledge: Basavanna vachanas, Kuvempu''s Ramayana Darshanam, Yakshagana, Hampi, Mysuru Dasara, Jog Falls, Coorg, Western Ghats biodiversity, Karnataka cuisine from filter kaapi to bisi bele bath to Udupi cuisine, Bengaluru IT culture. What''s next: continue to A2 advanced and B1 — more complex reading, writing, and fluent conversation. Shubhashayagalu! Neevu adbhuta kaela maaDiddiri!"},"examples":[{"sentence":"Neevu 120 Kannada lesson poorthi maaDiddiri — A1 inda A2 varege ondu adbhuta prayana itu, munde B1 ge saagona!","english":"You have completed 120 Kannada lessons — it was a wonderful journey from A1 to A2, let''s continue to B1!"},{"sentence":"Nimage oLLeya bhavishya aagali, neevu kalikuttiruva Kannada bhaashe nimma jiivana hecchaagi channagi maaDali anta ashiisisuttini.","english":"May good future come to you, I bless you that the Kannada language you are learning may make your life more beautiful."}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":20,"canDo":"I have completed 120 Kannada lessons — A1 + A2 foundation complete!"}}',
'{"items":[{"word":"prayana","translation":"journey/voyage","transliteration":"prayana","pronunciation":"PRA-ya-na","example":"ondu adbhuta prayana"},{"word":"poorthi maaDiddiri","translation":"you have completed (formal — you did it)","transliteration":"poorthi maaDiddiri","pronunciation":"POOR-thi MAA-did-di-ri","example":"120 lessons poorthi maaDiddiri"},{"word":"ashiisisuttini","translation":"I bless you (formal blessing — ashiisi = bless)","transliteration":"ashiisisuttini","pronunciation":"a-shii-SI-sut-ti-ni","example":"nimga ashiisisuttini"},{"word":"adbhuta kaela","translation":"wonderful work/achievement","transliteration":"adbhuta kaela","pronunciation":"ad-BHU-ta KAE-la","example":"neevu adbhuta kaela maaDiddiri"},{"word":"munde saagona","translation":"let''s continue/proceed forward","transliteration":"munde saagona","pronunciation":"MUN-de SAA-go-na","example":"B1 ge munde saagona"},{"word":"Shubhashayagalu","translation":"Congratulations/Best wishes (formal celebratory)","transliteration":"Shubhashayagalu","pronunciation":"shu-bha-SHA-ya-ga-lu","example":"Shubhashayagalu!"}]}',
'{"title":"120 Kannada lessons complete — Shubhashayagalu!","pattern":"Neevu X poorthi maaDiddiri = You have completed X. X inda Y varege prayana = journey from X to Y. Munde Y ge saagona = let''s continue to Y. Blessing: X aagali anta ashiisisuttini = I bless that X may happen. Review: A1 + A2 = foundation. Next: B1 = independence.","explanation":"Lesson 120 vocabulary summary — key words learned across 120 lessons: Greetings (Namaskara, Hegidiri), Family (amma/appa/ajja/ajji/anna/akka/tamma/tangi/doddappa/chikkappa), Food (oota, kaapi, idli, dosa, bisi bele bath, saaru), Numbers (ondu to saavira crore), Time (beLigge/madyaahna/saayankala/raatruu), Travel (hode/nodide/tinNde), Culture (Basavanna, Kuvempu, Dasara, Yakshagana, Hampi), Grammar (A1: basic tenses, negation; A2: reported speech, conditionals, participials, hortative, wishes, possibility). What to practice now: daily 15 minutes, conversation with native speakers, watch Kannada films with Kannada subtitles (Kannadigas enjoy helping learners!), read simple Kannada books. Keep going — B1 waits!","examples":[{"sentence":"Neevu ee 120 lessons alli Kannada bhaashe kalikuttiri — idu oNdu adbhuta prayana, nimage thumba dhanyavaadagaLu haagu Shubhashayagalu!","english":"You are learning Kannada in these 120 lessons — this is a wonderful journey, many thanks to you and congratulations!"},{"sentence":"Kannada kalikonDu Bengaluru ge hoda dinada inda ivaththina varege nimma jiivana hecchaagi channagi aagide anta nambuttiddeeni.","english":"I believe that from the day you started learning Kannada and went to Bengaluru until today your life has become more beautiful."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Shubhashayagalu means?","options":["Congratulations/Best wishes (formal)","Goodbye","Thank you","Welcome"],"correctAnswer":"Congratulations/Best wishes (formal)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"You have completed 120 Kannada lessons — it was a wonderful journey from A1 to A2, let''s continue to B1!","options":["Neevu 120 Kannada lesson poorthi maaDiddiri — A1 inda A2 varege ondu adbhuta prayana itu, munde B1 ge saagona!","Naanu 120 Kannada lesson poorthi maaDiddini — A1 inda A2 varege ondu adbhuta prayana itu, munde B1 ge saagona!","Neevu 100 Kannada lesson poorthi maaDiddiri — A1 inda A2 varege ondu adbhuta prayana itu, munde B1 ge saagona!","Neevu 120 Kannada lesson shuru maaDiddiri — A1 inda A2 varege ondu adbhuta prayana itu, munde B1 ge saagona!"],"correctAnswer":"Neevu 120 Kannada lesson poorthi maaDiddiri — A1 inda A2 varege ondu adbhuta prayana itu, munde B1 ge saagona!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nimage oLLeya bhavishya aagali, neevu kalikuttiruva Kannada bhaashe nimma jiivana hecchaagi channagi ___ anta ashiisisuttini.","options":["maaDali","maaDide","maaDuvudu","maaDabeku"],"correctAnswer":"maaDali"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You are learning Kannada in these 120 lessons — this is a wonderful journey, many thanks to you and congratulations!","wordBankItems":["Neevu","ee","120","lessons","alli","Kannada","bhaashe","kalikuttiri","—","idu","oNdu","adbhuta","prayana",",","nimage","thumba","dhanyavaadagaLu","haagu","Shubhashayagalu","!"],"correctAnswer":"Neevu ee 120 lessons alli Kannada bhaashe kalikuttiri — idu oNdu adbhuta prayana , nimage thumba dhanyavaadagaLu haagu Shubhashayagalu !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"ashiisisuttini means?","options":["I bless you (formal blessing)","I thank you","I congratulate you","I support you"],"correctAnswer":"I bless you (formal blessing)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

